        'rh.insight.addsip':    '💡 Increase SIP by ~<strong>{amount}/mo</strong> at {pct}% return to bridge the gap.',
        'rh.insight.corpusshort': '<span style="color:#92400e;font-weight:700">⚠️ Warning:</span> Corpus depletes at <strong>age {age}</strong> — {n} years short of life expectancy ({lifeExp}).',
        'rh.insight.corpuslasts': '✅ Corpus <strong>outlasts life expectancy</strong> (age {n}). Strong retirement foundation.',
        'rh.insight.medical':   '<span style="color:#be123c;font-weight:700">🏥 Healthcare note:</span> Medical costs projected at <strong>{pct}% p.a.</strong> (vs {genPct}% general inflation). Today\'s ₹{today}/mo medical spend inflates to <strong>{inflated}/mo</strong> by retirement — included in the numbers above.',
        'rh.insight.flat':      'ℹ️ Assumes flat contributions (no annual step-up) and current EPF 8.25% / PPF 7.1% rates till retirement. Depletion ages account for expenses continuing to inflate through retirement.',
        'rh.stress.insight.a':  '⚠️ A 30% crash in Year 1 turns a <strong>healthy corpus into depletion at age {n}</strong>. Your base case outlasts life expectancy — but a bad sequence erases that advantage. The 3-bucket strategy keeps 1–2 years of expenses in liquid assets so you never sell equity at the worst time.',
        'rh.stress.insight.b':  '⚠️ A 30% crash in Year 1 moves depletion from age <strong>{base} → {stress}</strong>. Keeping Bucket 1 (liquid, 1yr) intact means you ride out crashes without forced selling.',
        'rh.stress.insight.c':  '✅ Even with a 30% crash in Year 1, your corpus outlasts life expectancy. <strong>Excellent resilience.</strong> Your plan absorbs severe sequence-of-returns risk.',
