    function _t(key) {
        var d = _T[_lang] || _T.en;
        return (d[key] !== undefined ? d[key] : (_T.en[key] || key));
    }

    /* ── Lazy language loader ─────────────────────────────────
       Only English ships inline; hi/te/ta live in /i18n/<lang>.json
       (generated by scripts/split-i18n.js) and are fetched on demand.
       On fetch failure the UI stays English (_t falls back) and the
       next language tap retries. */
    var _langLoads = {};
    function loadLangDict(lang) {
        if (lang === 'en' || _T[lang]) return Promise.resolve();
        if (_langLoads[lang]) return _langLoads[lang];
        _langLoads[lang] = fetch('/i18n/' + lang + '.json', { signal: AbortSignal.timeout(8000) })
            .then(function(r) {
                if (!r.ok) throw new Error('HTTP ' + r.status);
                return r.json();
            })
            .then(function(data) {
                Object.keys(data).forEach(function(name) {
                    if (window[name]) window[name][lang] = data[name];
                });
            })
            .catch(function(err) {
                delete _langLoads[lang];
                console.warn('[i18n] failed to load', lang, err);
            });
        return _langLoads[lang];
    }



