                stddev:'நிலையான விலகல் வருமான ஏற்ற இறக்கத்தை அளவிடுகிறது. 15% வருமானம் மற்றும் 5% SD நிலையானது. அதே ஃபண்ட் 20% SD உடன் -5% முதல் 35% வரை செல்லலாம்.',
