                sortino:        'SWP (முறையான திரும்பப்பெறுதல்) தேவைப்படும் ஃபண்டுகளுக்கு சொர்டினோ மிகவும் பயனுள்ளது. குறைந்த சொர்டினோ என்பது சரிவுகளில் உங்கள் SWP கடுமையாக பாதிக்கப்படும் என்று பொருள்.',
