                directvsregular:'Zerodha Coin, Groww Direct, அல்லது நேரடியாக AMC இணையதளம் மூலம் டைரக்டுக்கு மாறுங்கள். 10 நிமிடங்கள் ஆகும், 20 ஆண்டுகளில் லட்சங்கள் மிச்சமாகும்.',
